+@page "/board"
+@using sv_5a44d1ff277743dba6d1fdf4d881b911
+@inject ITaskService TaskService
+@rendermode InteractiveServer
+
+<PageTitle>Kanban Board</PageTitle>
+
+<h2 class="mb-3">Project Board</h2>
+
+@if (isLoading)
+{
+    <div class="d-flex justify-content-center my-5">
+        <div class="spinner-border" role="status">
+            <span class="visually-hidden">Loading...</span>
+        </div>
+    </div>
+}
+else if (errorMessage is not null)
+{
+    <div class="alert alert-danger" role="alert">
+        <strong>Error:</strong> @errorMessage
+    </div>
+}
+else
+{
+    <!-- Stats Bar -->
+    <div class="row g-2 mb-3">
+        <div class="col">
+            <div class="card text-center">
+                <div class="card-body py-2">
+                    <div class="fw-bold fs-4">@tasks.Count</div>
+                    <small class="text-muted">Total Tasks</small>
+                </div>
+            </div>
+        </div>
+        @foreach (var col in columns)
+        {
+            <div class="col">
+                <div class="card text-center">
+                    <div class="card-body py-2">
+                        <div class="fw-bold fs-4">@GetTasksForColumn(col).Count</div>
+                        <small class="text-muted">@col</small>
+                    </div>
+                </div>
+            </div>
+        }
+        <div class="col">
+            <div class="card text-center border-danger">
+                <div class="card-body py-2">
+                    <div class="fw-bold fs-4 text-danger">@tasks.Count(t => t.DueDate < DateTime.Today)</div>
+                    <small class="text-muted">Overdue</small>
+                </div>
+            </div>
+        </div>
+    </div>
+
+    <!-- Search Bar -->
+    <div class="mb-3">
+        <input type="text" class="form-control" placeholder="Search tasks by title..."
+               @bind="searchText" @bind:event="oninput" />
+    </div>
+
+    <!-- Kanban Columns -->
+    <div class="row g-3">
+        @for (int i = 0; i < columns.Length; i++)
+        {
+            var colIndex = i;
+            var column = columns[colIndex];
+            var columnTasks = GetFilteredTasksForColumn(column);
+
+            <div class="col-md-4">
+                <div class="card h-100">
+                    <div class="card-header d-flex justify-content-between align-items-center">
+                        <h5 class="mb-0">@column</h5>
+                        <span class="badge bg-secondary">@GetTasksForColumn(column).Count</span>
+                    </div>
+                    <div class="card-body d-flex flex-column gap-2" style="min-height: 200px;">
+                        @foreach (var task in columnTasks)
+                        {
+                            <div class="card shadow-sm">
+                                <div class="card-body p-2">
+                                    <div class="d-flex justify-content-between align-items-start mb-1">
+                                        <strong class="me-2">@task.Title</strong>
+                                        <span class="badge @GetPriorityClass(task.Priority)">@task.Priority</span>
+                                    </div>
+                                    <div class="text-muted small mb-2">
+                                        <span>@task.Assignee</span>
+                                        <span class="float-end">@task.DueDate.ToString("MMM dd")</span>
+                                    </div>
+                                    <div class="d-flex gap-1">
+                                        @if (colIndex > 0)
+                                        {
+                                            var leftStatus = columns[colIndex - 1];
+                                            <button class="btn btn-outline-secondary btn-sm"
+                                                    @onclick="() => MoveTask(task.Id, leftStatus)"
+                                                    disabled="@isMoving">
+                                                &larr; Move Left
+                                            </button>
+                                        }
+                                        @if (colIndex < columns.Length - 1)
+                                        {
+                                            var rightStatus = columns[colIndex + 1];
+                                            <button class="btn btn-outline-secondary btn-sm"
+                                                    @onclick="() => MoveTask(task.Id, rightStatus)"
+                                                    disabled="@isMoving">
+                                                Move Right &rarr;
+                                            </button>
+                                        }
+                                    </div>
+                                </div>
+                            </div>
+                        }
+
+                        <!-- Add Task Form -->
+                        @if (addingToColumn == column)
+                        {
+                            <div class="card border-primary mt-auto">
+                                <div class="card-body p-2">
+                                    <div class="mb-2">
+                                        <input type="text" class="form-control form-control-sm"
+                                               placeholder="Title" @bind="newTitle" />
+                                    </div>
+                                    <div class="mb-2">
+                                        <input type="text" class="form-control form-control-sm"
+                                               placeholder="Assignee" @bind="newAssignee" />
+                                    </div>
+                                    <div class="mb-2">
+                                        <select class="form-select form-select-sm" @bind="newPriority">
+                                            <option value="High">High</option>
+                                            <option value="Medium">Medium</option>
+                                            <option value="Low">Low</option>
+                                        </select>
+                                    </div>
+                                    <div class="mb-2">
+                                        <input type="date" class="form-control form-control-sm"
+                                               @bind="newDueDate" />
+                                    </div>
+                                    <div class="d-flex gap-1">
+                                        <button class="btn btn-primary btn-sm" @onclick="SaveTask"
+                                                disabled="@isSaving">
+                                            @if (isSaving) { <span class="spinner-border spinner-border-sm me-1"></span> }
+                                            Save
+                                        </button>
+                                        <button class="btn btn-outline-secondary btn-sm"
+                                                @onclick="CancelAdd" disabled="@isSaving">
+                                            Cancel
+                                        </button>
+                                    </div>
+                                </div>
+                            </div>
+                        }
+                        else
+                        {
+                            <button class="btn btn-outline-primary btn-sm mt-auto"
+                                    @onclick="() => StartAdd(column)">
+                                + Add Task
+                            </button>
+                        }
+                    </div>
+                </div>
+            </div>
+        }
+    </div>
+}
+
+@code {
+    private readonly string[] columns = ["To Do", "In Progress", "Done"];
+
+    private List<TaskItem> tasks = new();
+    private bool isLoading = true;
+    private bool isMoving;
+    private bool isSaving;
+    private string? errorMessage;
+    private string searchText = string.Empty;
+
+    // Add-task form state
+    private string? addingToColumn;
+    private string newTitle = string.Empty;
+    private string newAssignee = string.Empty;
+    private string newPriority = "Medium";
+    private DateTime newDueDate = DateTime.Today.AddDays(7);
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            tasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private List<TaskItem> GetTasksForColumn(string status) =>
+        tasks.Where(t => t.Status == status).ToList();
+
+    private List<TaskItem> GetFilteredTasksForColumn(string status) =>
+        tasks.Where(t => t.Status == status &&
+            (string.IsNullOrWhiteSpace(searchText) ||
+             t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)))
+            .ToList();
+
+    private static string GetPriorityClass(string priority) => priority switch
+    {
+        "High" => "bg-danger",
+        "Medium" => "bg-warning text-dark",
+        "Low" => "bg-success",
+        _ => "bg-secondary"
+    };
+
+    private async Task MoveTask(int taskId, string newStatus)
+    {
+        isMoving = true;
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var idx = tasks.FindIndex(t => t.Id == taskId);
+            if (idx >= 0)
+            {
+                var old = tasks[idx];
+                tasks[idx] = old with { Status = newStatus };
+            }
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isMoving = false;
+        }
+    }
+
+    private void StartAdd(string column)
+    {
+        addingToColumn = column;
+        newTitle = string.Empty;
+        newAssignee = string.Empty;
+        newPriority = "Medium";
+        newDueDate = DateTime.Today.AddDays(7);
+    }
+
+    private void CancelAdd() => addingToColumn = null;
+
+    private async Task SaveTask()
+    {
+        if (string.IsNullOrWhiteSpace(newTitle) || addingToColumn is null)
+            return;
+
+        isSaving = true;
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(newTitle, newAssignee, newPriority, newDueDate);
+            // The service creates with "To Do" status by default; update if needed
+            if (created.Status != addingToColumn)
+            {
+                await TaskService.UpdateTaskStatusAsync(created.Id, addingToColumn);
+                created = created with { Status = addingToColumn };
+            }
+            tasks.Add(created);
+            addingToColumn = null;
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isSaving = false;
+        }
+    }
+}
+

